// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(c.owner());
        vm.startPrank(c.owner());
        c.setOwner(caller);
        vm.stopPrank();

        address ownerBefore = c.owner();

        vm.prank(caller);
        uint256 gasBefore = gasleft();
        try c.setOwner(newOwner) returns (bool) {
            assertTrue(c.owner() == newOwner);
        } catch {
            assertTrue(c.owner() == ownerBefore);
        }
    }
}
